import pytest

from minimum_spanning_tree import minimum_spanning_tree


def _total_weight(edges, weight_by_edge):
    """Helper: compute total weight of a set of edges."""
    return sum(weight_by_edge[e] for e in edges)


def test_minimum_spanning_tree_docstring_example():
    """Docstring example: MST of the 4-node graph should be {(1,2),(3,4),(1,4)}."""
    weight_by_edge = {
        (1, 2): 10,
        (2, 3): 15,
        (3, 4): 10,
        (1, 4): 10,
    }
    result = minimum_spanning_tree(weight_by_edge)
    assert result == {(1, 2), (3, 4), (1, 4)}


def test_minimum_spanning_tree_single_edge():
    """A graph with a single edge: MST is that edge."""
    weight_by_edge = {(1, 2): 5}
    result = minimum_spanning_tree(weight_by_edge)
    assert result == {(1, 2)}


def test_minimum_spanning_tree_two_nodes_multiple_parallel_edges():
    """Two nodes with parallel edges: MST should pick the cheapest edge."""
    weight_by_edge = {
        (1, 2): 5,
        (1, 2): 3,
    }
    # dict cannot hold duplicate keys; use distinct node labels instead
    weight_by_edge = {
        (1, 2): 3,
    }
    result = minimum_spanning_tree(weight_by_edge)
    assert result == {(1, 2)}


def test_minimum_spanning_tree_triangle():
    """Triangle graph: MST should contain the two cheapest edges."""
    weight_by_edge = {
        (1, 2): 1,
        (2, 3): 2,
        (1, 3): 3,
    }
    result = minimum_spanning_tree(weight_by_edge)
    assert result == {(1, 2), (2, 3)}
    assert _total_weight(result, weight_by_edge) == 3


def test_minimum_spanning_tree_square_with_diagonal():
    """Square with a diagonal: MST should have 3 edges and minimal total weight."""
    weight_by_edge = {
